        cardBg: 'rgba(17, 17, 17, 0.9)'
      }
    },
    {
      id: 'dark-gradient',
      name: 'Degradado Oscuro',
      type: 'dark',
      colors: {
        bgPrimary: 'linear-gradient(135deg, #0f0f23 0%, #1a1a2e 50%, #16213e 100%)',
        bgSecondary: 'rgba(26, 26, 46, 0.8)',
        bgTertiary: 'rgba(22, 33, 62, 0.9)',
        textPrimary: '#ffffff',
        textSecondary: '#e8e8ff',
        textMuted: '#b8b8d8',
        accentPrimary: '#00d4ff',
        accentSecondary: '#0099cc',
        borderColor: '#2a2a4a',
        shadowColor: 'rgba(0, 212, 255, 0.3)',
        navBg: 'rgba(15, 15, 35, 0.95)',
        cardBg: 'rgba(26, 26, 46, 0.8)'
      }
    },
    {
      id: 'dark-cyber',
      name: 'Cyberpunk',
      type: 'dark',
      colors: {
        bgPrimary: '#0a0a0a',
        bgSecondary: '#1a1a1a',
        bgTertiary: '#2a2a2a',
        textPrimary: '#00ff41',
        textSecondary: '#00cc33',
        textMuted: '#008025',
        accentPrimary: '#ff0080',
        accentSecondary: '#ff66b2',
        borderColor: '#00ff41',
        shadowColor: 'rgba(0, 255, 65, 0.4)',
        navBg: 'rgba(10, 10, 10, 0.95)',
        cardBg: 'rgba(26, 26, 26, 0.9)'
      }
    },
    {
      id: 'dark-royal',
      name: 'Real',
      type: 'dark',
      colors: {
        bgPrimary: '#1a0f1f',
        bgSecondary: '#2d1b3d',
        bgTertiary: '#3d2757',
        textPrimary: '#ffd700',
        textSecondary: '#ffed4e',
        textMuted: '#b8941f',
        accentPrimary: '#c41e3a',
        accentSecondary: '#dc143c',
        borderColor: '#4a2c5d',
        shadowColor: 'rgba(255, 215, 0, 0.3)',
        navBg: 'rgba(26, 15, 31, 0.95)',
        cardBg: 'rgba(45, 27, 61, 0.9)'
      }
    },
    {
      id: 'dark-ocean',
      name: 'Océano Profundo',
      type: 'dark',
      colors: {
        bgPrimary: '#001122',
        bgSecondary: '#002244',
        bgTertiary: '#003366',
        textPrimary: '#e6f3ff',
        textSecondary: '#b3d9ff',
        textMuted: '#80bfff',
