        textPrimary: '#ff6b35',
        textSecondary: '#ff8c42',
        textMuted: '#cc5a2a',
        accentPrimary: '#ff4500',
        accentSecondary: '#ff6347',
        borderColor: '#4a2c2c',
        shadowColor: 'rgba(255, 107, 53, 0.4)',
        navBg: 'rgba(26, 15, 15, 0.95)',
        cardBg: 'rgba(45, 27, 27, 0.9)'
      }
    }
  ];

