      colors: {
        bgPrimary: 'linear-gradient(135deg, #f8fafc 0%, #e2e8f0 50%, #cbd5e1 100%)',
        bgSecondary: 'rgba(248, 250, 252, 0.8)',
        bgTertiary: 'rgba(226, 232, 240, 0.9)',
