        textSecondary: '#4a5568',
        textMuted: '#718096',
        accentPrimary: '#ff6b9d',
        accentSecondary: '#ff8fab',
        borderColor: '#e2e8f0',
        shadowColor: 'rgba(255, 107, 157, 0.15)',
        navBg: 'rgba(254, 254, 254, 0.95)',
        cardBg: 'rgba(248, 249, 255, 0.9)'
